cd /private/var/folders/yw/fbsfvfm95956m4m6yfd49z_c0000gn/T/tair-expanded-project-8ove1z4_/workspace && node --input-type=module -e "
import { uniqueStrings } from './unique_base.mjs';

// Basic dedup preserving order
const a = ['apple', 'banana', 'apple', 'cherry', 'banana'];
const r1 = uniqueStrings(a);
console.log('basic:', JSON.stringify(r1));
console.assert(JSON.stringify(r1) === JSON.stringify(['apple','banana','cherry']), 'basic failed');

// Case sensitivity
const b = ['Apple', 'apple', 'APPLE', 'apple'];
const r2 = uniqueStrings(b);
console.log('case:', JSON.stringify(r2));
console.assert(JSON.stringify(r2) === JSON.stringify(['Apple','apple','APPLE']), 'case failed');

// Whitespace not trimmed
const c = ['  x', 'x', '  x', 'x  '];
const r3 = uniqueStrings(c);
console.log('whitespace:', JSON.stringify(r3));
console.assert(JSON.stringify(r3) === JSON.stringify(['  x','x','x  ']), 'whitespace failed');

// No mutation of input
const d = ['a','b','a'];
const copy = [...d];
uniqueStrings(d);
console.assert(JSON.stringify(d) === JSON.stringify(copy), 'input mutated');

// Empty input
console.log('empty:', JSON.stringify(uniqueStrings([])));

// Duplicate empty strings
console.log('empty strings:', JSON.stringify(uniqueStrings(['','','a',''])));

console.log('All checks passed.');
"

